/* The PS1's sound requests as the arcade's effect codes (music.md section 12b; the table is generated by sounds.py --c-table:
 * numbers only). A request is known by two FNV-1a 32 keys: of the bank slot's VAB header and of the sound's run of command
 * entries. */
#ifndef ARCADE_SOUNDS_H
#define ARCADE_SOUNDS_H

#include <stdint.h>

struct arcade_sound {
    uint32_t key_vab, key_run;   /* sorted by these, for a binary search */
    uint16_t code0, code1;       /* the arcade effect for side 0 and side 1; 0xffff: none (the PS1's own sound plays) */
    uint8_t method, flags;       /* how the mapping was found (sounds.py); bit 0 of flags: a weak sample match */
};

/* The arcade's pan of an object dx pixels (0 .. 0x17f) right of the camera: pan_first plus the number of edges at or below dx,
 * minus one (16 is the centre of 0 .. 32). */
extern const unsigned arcade_sound_pan_first;
extern const unsigned short arcade_sound_pan_edges[15];
extern const struct arcade_sound arcade_sounds[];
extern const unsigned arcade_sound_count;

#endif
